checks=[]
def check(source,q,a,wr,why):
 checks.append(dict(id=f'304-c{len(checks)+1:02}',source=source,section=d['questions'][source-1]['section'],q=q,correct=a,distractors=wr.split('|'),teach=why,answer=a))
check(1,'A manager uses experience to apply a sales report. Which DIKW level is this?','Knowledge','Data|Information|Wisdom','Applying information using understanding is knowledge. Wisdom is the judgment used to choose a sensible action after considering the situation.')
check(3,'Which IS component is the cashier who uses the checkout system?','People','Software|Data|Processes','The cashier is a human participant. The steps they follow are the process; the app they use is software.')
check(4,'Which hardware holds active work temporarily?','RAM','Persistent storage|CPU|Network adapter','RAM is temporary working space. The CPU executes instructions; persistent storage keeps saved files.')
check(9,'A business charges a recurring fee for continued access. Which model?','Subscription','Marketplace|Franchise|Value-added reseller','Recurring access fees characterize subscriptions. A marketplace connects buyers and sellers; a franchise licenses a business approach.')
check(9,'A seller bundles equipment with installation and training. Which slide example fits?','Value-added reseller','Subscription|Advertising|Marketplace','The seller adds services to another company’s product, creating a more useful bundle.')
check(11,'In DSRP, comparing a customer’s and an employee’s views uses which pattern?','Perspectives','Distinctions|Systems|Relationships','Perspectives are viewpoints. Different people can experience the same process differently.')
check(11,'In DSRP, asking what belongs inside a system and what larger whole it belongs to uses which pattern?','Systems','Perspectives|Relationships|Distinctions','Systems thinking includes nested parts and wholes. Distinctions instead identify what something is and is not.')
check(11,'In DSRP, asking how stock shortages affect delivery uses which pattern?','Relationships','Perspectives|Distinctions|Systems','You are examining how one thing affects another: a relationship.')
check(13,'Which process model shows the proposed improved workflow?','To-be','As-is|Hardware architecture|Organizational chart','To-be describes intended future work. As-is captures how the work currently happens.')
check(13,'Which detail belongs in a process model?','Who performs an activity and which decision determines the next step','Only company revenue totals|Only hardware serial numbers|Only employee job titles without workflow','A useful process model describes work, actors, decisions, and sequence so handoffs and problems become visible.')
check(18,'A salon performs a customer’s haircut. Which core process is this work?','Production','Procurement|Accounting|Architecture','Production includes creating a service. It is not limited to making factory goods.')
check(19,'A bakery identifies a flour shortage and sends an order to a supplier. Which process?','Procurement','Fulfillment|Production|Accounting','The bakery is buying resources it needs. From the supplier’s side, supplying that order is fulfillment.')
check(19,'Which is a sensible output of the accounting process?','Checked financial records and reports','A newly baked loaf|A request to order flour|An unprocessed customer order','Accounting takes financial events as inputs, checks and organizes them, and produces records and reports.')
check(19,'Which output belongs to procurement?','Accepted supplies and purchase/payment records','Only a sales advertisement|Only a finished product made from raw materials|Only a customer’s delivery confirmation','Procurement gets resources into the organization. Production later transforms those resources.')
check(19,'Which input most directly starts fulfillment?','A customer order','A department’s internal purchase requisition|A year-end financial statement|An architectural framework','Fulfillment follows a customer’s request through preparation, delivery, and payment.')
check(19,'An employee asks the purchasing department to buy a monitor. Which document is this?','Purchase requisition','Purchase order|Sales order|Vendor invoice','The request is still internal. The organization later sends a purchase order to the selected seller.')
check(19,'The seller sends a bill. What is it called from the buyer’s perspective?','Vendor invoice','Sales order|Purchase requisition|Purchase order','The buyer receives a request to pay its vendor. The same bill is a sales invoice from the seller’s perspective.')
check(20,'A process gets faster but doubles its error rate. What should you conclude?','Evaluate speed and quality together against the goal','It is definitely better because time fell|It is definitely more effective because errors rose|Ignore quality when evaluating a process','Improvement must serve the intended outcome. Fast incorrect orders may not satisfy the goal.')
check(22,'Removing one duplicate approval from the existing workflow is usually what?','BPI','BPR|ERP II|SOA','It is a small adjustment to the current workflow rather than fundamental redesign.')
check(23,'Replacing the entire order-handling approach with a new cross-functional design is what?','BPR','BPI|FAIS|DIKW','The basic design and responsibilities are being reconsidered. That is the radical scope of re-engineering.')
check(27,'Is an EA framework the same thing as the company’s architecture?','No; the framework structures the work, while architecture is the company’s design','Yes; both mean the installed hardware|Yes; both mean only the database|No; architecture means goals only and a framework means profits','A framework supplies ways to describe and develop a design. The resulting architecture is specific to the enterprise.')
check(29,'Defining customer and order records belongs most directly to which architecture layer?','Data','Business|Application|Technology','Data architecture concerns the structure and management of data assets, including these records.')
check(29,'Defining how ordering and inventory apps interact belongs to which layer?','Application','Business|Data|Technology','Application architecture describes applications and their interactions in support of business work.')
check(29,'Defining the company’s fulfillment process and decision responsibilities belongs to which layer?','Business','Application|Data|Technology','Business architecture covers processes, organization, strategy, and governance.')
check(29,'Defining required servers, supporting software, and networks belongs to which layer?','Technology','Application|Data|Business','Technology architecture describes the capabilities needed to run applications and data services.')
check(32,'Must SOA services be hosted in the cloud?','No; reusable services can run on premises or in the cloud','Yes; any locally hosted service stops being SOA|Yes; SOA simply means any website|No; SOA forbids cloud services','SOA describes software organization around services. Hosting location is a separate choice; the slide uses a simplified cloud association.')
check(42,'Two branches use the same order form but never share records. What is present?','Standardization without integration','Integration without standardization|Both full integration and standardization|Neither, because all forms must be different','The form is consistent, but work and records are not connected between the branches.')
check(43,'A new sale automatically updates inventory and accounting. What does this illustrate?','Integration','Isolation|Decentralization by itself|Data collection without sharing','The transaction connects several business functions so each can act on shared information.')
check(47,'Does “single version of the truth” mean an ERP automatically fixes wrong data?','No; shared records still require accurate inputs and controls','Yes; shared storage guarantees all facts are correct|Yes; only separate databases can contain errors|No; ERP prevents all departments from viewing records','Shared data reduces conflicting copies, but a wrong value can still be shared widely. Data quality remains essential.')
check(49,'Moving old records into ERP is called what?','Data migration','Process differentiation|Business strategy|Functional specialization','Migration is the transfer of data into the new environment, where formats and accuracy need checking.')
check(51,'A supplier accesses a buyer’s purchasing process online. Which ERP II feature does this show?','Interorganizational support','Department isolation|Hardware centralization only|Removal of all supplier involvement','The work crosses company boundaries, extending the internal integration emphasized by ERP I.')
d['checks']=checks
sorts=[(1,'Build the DIKW order',['Data','Information','Knowledge','Wisdom'],'Facts become meaningful information, then usable understanding, then informed judgment.'),(37,'Translate strategy into a working system',['Strategic goals','Business requirements','Architectural requirements','Infrastructure choices'],'First decide the goal, then required business behavior, then the design, then concrete technology.'),(19,'Procurement: order the main steps',['Identify the need','Request approval if required','Select vendor and send purchase order','Receive and inspect resources','Pay the vendor'],'In this simplified flow, know the need before ordering and inspect delivery before paying. Contract payment timing can vary.'),(19,'Fulfillment: order this pay-after-delivery example',['Receive customer order','Record sales order','Prepare goods or service','Deliver to the customer','Bill and receive payment'],'The customer’s order starts the flow. This example bills after delivery; other businesses collect payment earlier.'),(21,'BPM: arrange one management cycle',['Design the process','Execute the process','Monitor results','Evaluate performance','Improve and repeat'],'Work is designed, used, checked, and improved. The cycle then continues.'),(13,'Build a simple order-check flow',['Receive an order','Check stock availability','Decide whether stock is sufficient','Prepare the available order','Deliver the order'],'This simplified path assumes enough stock. A full activity diagram also shows the no-stock branch.')]
d['sorts']=[dict(id=f'304-s{i+1}',source=n,section=d['questions'][n-1]['section'],q=t,items=items,teach=why) for i,(n,t,items,why) in enumerate(sorts)]
